JOIN dmcode.cm_guoku_dimnsn c ON a.app_org = c.guoku_id
JOIN inspection.inspection_sysuser_talentpool_relation d ON a.add_user = d.SYS_USERID
JOIN inspection.cm_guoku_talentpool e ON d.TALENTPOOL_ID = e.UUID
LEFT JOIN inspection.inspection_sysuser_talentpool_relation f ON a.app_user = f.SYS_USERID
LEFT JOIN inspection.cm_guoku_talentpool g ON f.TALENTPOOL_ID = g.UUID
JOIN `jeecg-boot-os`.sys_role h ON a.app_role = h.id
WHERE 1=1

    AND a.subject_id = #{params.subject_id}


    AND ${params.condition} = #{params.ID}


    AND a.app_role = #{params.app_role}


    AND a.app_org = #{params.app_org}


    AND a.app_result = #{params.app_result}


    AND a.add_user = #{params.add_user}

order by app_time desc

SELECT
count(1)
FROM
inspection.inspection_approval a
JOIN ${params.tablename} b on a.subject_id = ${params.tableid}
JOIN dmcode.cm_guoku_dimnsn c ON a.app_org = c.guoku_id
JOIN inspection.inspection_sysuser_talentpool_relation d ON a.add_user = d.SYS_USERID
JOIN inspection.cm_guoku_talentpool e ON d.TALENTPOOL_ID = e.UUID
LEFT JOIN inspection.inspection_sysuser_talentpool_relation f ON a.app_user = f.SYS_USERID
LEFT JOIN inspection.cm_guoku_talentpool g ON f.TALENTPOOL_ID = g.UUID
JOIN `jeecg-boot-os`.sys_role h ON a.app_role = h.id
WHERE 1=1

